<script setup lang="ts">
import {computed,ref} from 'vue'
import {onLoad,onShow} from '@dcloudio/uni-app'
import {closetApi,type ClosetTask,type ProcessingChoice} from '../../services/api'
import {closetTools} from '../../services/closet'
import {useProcessingStore} from '../../stores/processing'
import AuthImage from '../../components/AuthImage.vue'
import QuickIntake from '../../components/closet/QuickIntake.vue'
import BatchIntake from '../../components/closet/BatchIntake.vue'
import GarmentEdgeHelp from '../../components/closet/GarmentEdgeHelp.vue'
import {choosePhotos,errorText,wardrobe} from '../../components/closet/navigation'
import { useAppearance } from '../../composables/useAppearance'
const { pageStyle } = useAppearance()
const entry=ref('单件处理'),quickEnabled=ref(false),file=ref(''),fileSize=ref(0),fileName=ref(''),mode=ref<Exclude<ClosetTask['mode'],'图片整理'>>('识别并整理'),busy=ref(false),error=ref(''),configError=ref(''),quotaError=ref(''),quotaLeft=ref<number|null>(null),quotaLimit=ref<number|null>(null),restage=ref(true),precut=ref(false),postcut=ref(true),rotationDegrees=ref(0),reuseTransparency=ref(false),generationChoices=ref<ProcessingChoice[]>([]),recognitionChoices=ref<ProcessingChoice[]>([]),generationChoice=ref(''),recognitionChoice=ref(''),advanced=ref<string[]>([]),help=ref(false)
let preferred=''
const entries=computed(()=>[...(quickEnabled.value?['快速入柜']:[]),'单件处理','多件整理']),isAI=computed(()=>mode.value!=='本地贴纸'),configured=computed(()=>!isAI.value||recognitionChoices.value.length>0&&(mode.value==='仅识别'||generationChoices.value.length>0)),disabled=computed(()=>!file.value||!configured.value||isAI.value&&(!!configError.value||!!quotaError.value||quotaLeft.value===null||quotaLeft.value===0))
const modes=[{value:'识别并整理',title:'识别并整理',body:'填写信息，整理照片并制作透明贴纸。',suitable:'适合自拍、穿着照或需要整理外观的单件。',cost:'识别 1 次 + 整理 1 次 AI 额度 · 需要等待模型'},{value:'仅识别',title:'仅识别信息',body:'自动填写信息，保留原照片。',suitable:'照片已拍得满意，无需改变外观。',cost:'1 次 AI 任务额度 · 不生成新图片'},{value:'本地贴纸',title:'本地去背景',body:'保留照片里的外观，衣物信息自己填写。',suitable:'适合平铺或悬挂；穿着照可能保留人物。',cost:'0 次 AI 额度 · 不发送云端'}]
const getButtonText=()=>{if(busy.value)return'正在上传并提交…';if(isAI.value&&quotaLeft.value===0)return'今日 AI 额度已用完';if(!file.value)return'选择照片后开始处理';if(mode.value==='仅识别')return'开始识别衣物信息';if(mode.value==='本地贴纸')return'开始本地去背景';return'识别并整理'}
async function prepare(){const results=await Promise.allSettled([closetApi.quota(),closetApi.processingChoices(),closetTools.capabilities()]);const [q,c,f]=results;if(q.status==='fulfilled'){quotaLeft.value=Math.max(0,q.value.limit-q.value.used);quotaLimit.value=q.value.limit;quotaError.value=''}else quotaError.value='暂时无法读取今日额度，请稍后重试。本地去背景仍可使用。';if(c.status==='fulfilled'){generationChoices.value=c.value.generation;recognitionChoices.value=c.value.recognition;generationChoice.value||=c.value.generation[0]?.value||'';recognitionChoice.value||=c.value.recognition[0]?.value||'';configError.value=''}else configError.value=errorText(c.reason,'暂时无法读取模型配置。本地去背景仍可使用。');if(f.status==='fulfilled'){quickEnabled.value=f.value.quickIntake;if(!preferred&&quickEnabled.value){entry.value='快速入柜';preferred='quick'}}}
async function choose(source:'album'|'camera'){if(busy.value)return;try{const photo=(await choosePhotos(source))[0];if(!photo)return;if(photo.size>50*1024*1024)throw new Error('图片不能超过 50 MB。');const info=await uni.getImageInfo({src:photo.tempFilePath}) as {type?:string};if(!['jpeg','jpg','png'].includes(info.type||''))throw new Error('请选择 JPEG 或 PNG 图片，HEIC 请先转换为 JPEG。');file.value=photo.tempFilePath;fileName.value=photo.tempFilePath.split('/').pop()||'照片';fileSize.value=photo.size;rotationDegrees.value=0;error.value=''}catch(e){error.value=errorText(e)}}
async function submit(){if(busy.value||disabled.value)return;busy.value=true;error.value='';try{const generation=JSON.parse(generationChoice.value||'{}'),recognition=JSON.parse(recognitionChoice.value||'{}');const task=await closetApi.create(file.value,mode.value,{restage:restage.value,precut:precut.value,postcut:postcut.value,rotationDegrees:rotationDegrees.value,transparencyPolicy:reuseTransparency.value?'AUTO':'FORCE',generationProvider:generation.provider,generationModel:generation.model,recognitionProvider:recognition.provider,recognitionModel:recognition.model});useProcessingStore().trackTask(task,true);uni.redirectTo({url:`/pkg-closet/garment/index?id=${encodeURIComponent(task.garmentId)}&task=${encodeURIComponent(task.id)}`})}catch(e){error.value=errorText(e,'提交失败，照片仍保留在此处。')}finally{busy.value=false}}
onLoad(q=>{preferred=String(q?.mode||'');entry.value=preferred==='multiple'?'多件整理':'单件处理'});onShow(()=>void prepare())
</script>
<template><page-meta :page-style="pageStyle" /><view class="page closet-page"><wd-button type="text" @click="wardrobe">返回衣柜</wd-button><view class="heading"><text class="title">添加衣物</text><text class="subtitle">{{entry==='快速入柜'?'一张照片一件衣物，拍完就能继续下一件。':entry==='多件整理'?'多张单件照、多件同框或自拍，分开整理后逐件核对。':'一件衣物，用单件工具更直接；多件照片，再选择批量整理。'}}</text></view><wd-segmented v-model:value="entry" :options="entries" :disabled="busy"/>
 <QuickIntake v-if="entry==='快速入柜'"/><BatchIntake v-if="entry==='多件整理'" embedded/>
 <template v-if="entry==='单件处理'"><view class="section"><text class="section-title">衣物照片</text><text class="hint">每次一张 · 一件衣物</text><view v-if="!file" class="empty"><wd-icon name="picture" size="70rpx"/><text class="section-title">选一张想收进衣柜的照片</text><text class="subtitle">平铺、悬挂或自拍都可以，让想录入的衣物完整入镜</text></view><view v-else class="preview"><view class="rotated" :style="{transform:`rotate(${rotationDegrees}deg)`}"><AuthImage :src="file"/></view></view><view class="actions"><wd-button :disabled="busy" @click="choose('album')">{{file?'更换照片':'选择照片'}}</wd-button><wd-button plain :disabled="busy" @click="choose('camera')">拍一张照片</wd-button><wd-button v-if="file" plain :disabled="busy" @click="rotationDegrees=(rotationDegrees+90)%360">旋转</wd-button></view><text v-if="file" class="hint">{{fileName}} · {{(fileSize/1024/1024).toFixed(1)}} MB</text><text class="hint">JPEG / PNG · 最大 50 MB</text><text class="subtitle">T恤、衬衫、外套、裤裙、鞋帽包及配饰均可录入。</text></view>
 <view class="section"><view class="row"><text class="section-title">处理方式</text><wd-button size="small" type="text" @click="help=true">怎么选择</wd-button></view><wd-radio-group v-model="mode" :disabled="busy"><view v-for="option in modes" :key="option.value" class="mode"><wd-radio :value="option.value">{{option.title}}</wd-radio><text class="hint">{{option.body}}</text></view></wd-radio-group></view>
 <wd-collapse v-model="advanced"><wd-collapse-item title="按自己的习惯调整" name="options"><text class="subtitle">默认已经替你选好，想调整时再打开就好。</text><wd-picker v-if="isAI&&recognitionChoices.length" v-model="recognitionChoice" :columns="recognitionChoices" :disabled="busy" label="识图模型"/><template v-if="mode==='识别并整理'"><wd-picker v-if="generationChoices.length" v-model="generationChoice" :columns="generationChoices" :disabled="busy" label="图片模型"/><view class="option"><view><text>摆正并适度整理</text><text class="hint">减轻随机褶皱，保留衣物原款</text></view><wd-switch v-model="restage" :disabled="busy"/></view><view class="option"><view><text>先去掉原背景</text><text class="hint">适合复杂背景的单件照片；穿着照会自动跳过</text></view><wd-switch v-model="precut" :disabled="busy"/></view><view class="option"><view><text>制作透明贴纸</text><text class="hint">方便之后放进穿搭画板</text></view><wd-switch v-model="postcut" :disabled="busy"/></view></template><view v-if="mode==='本地贴纸'" class="option"><view><text>背景已经透明，直接制作贴纸</text><text class="hint">仅适用于已经去干净背景的衣物图；截图的透明圆角不算</text></view><wd-switch v-model="reuseTransparency" :disabled="busy"/></view></wd-collapse-item></wd-collapse>
 <wd-notice-bar v-if="isAI&&(configError||quotaError||!configured)" class="notice" :text="configError||quotaError||'当前模式需要的模型未配置。你可以先使用本地去背景，或联系管理员。'" :scrollable="false" wrapable/><wd-button v-if="configError||quotaError" size="small" type="text" @click="prepare">重试</wd-button><wd-notice-bar v-if="error" class="notice" :text="error" type="danger" :scrollable="false" wrapable/>
 <view class="section"><text>当前：{{modes.find(m=>m.value===mode)?.title}} · {{isAI?'1 次 AI 任务额度':'0 次 AI 额度'}}</text><text v-if="isAI" class="hint">今日剩余 {{quotaLeft===null?'—':quotaLeft}} / {{quotaLimit??'—'}} 次</text><view class="actions"><wd-button block :loading="busy" :disabled="disabled" @click="submit">{{getButtonText()}}</wd-button></view><text class="hint">{{isAI?'照片将发送到已配置的模型服务。处理时长由模型决定，结果返回后请检查衣物细节。':'照片由你的衣柜服务本地处理，不发送到云端模型。衣物信息可以稍后慢慢填写。'}}</text></view></template>
 <GarmentEdgeHelp v-if="entry!=='快速入柜'"/><wd-popup v-model="help" position="bottom" closable><view class="sheet"><text class="sheet-title">怎么选择处理方式</text><view v-for="option in modes" :key="option.value" class="field-row"><text>{{option.title}}</text><text class="subtitle">{{option.suitable}}</text><text class="hint">{{option.cost}}</text></view></view></wd-popup>
</view></template>
<style lang="scss" scoped>@import '../../components/closet/closet.scss';.empty{padding:48rpx 0;text-align:center}.rotated{width:100%;height:100%}.mode{padding:24rpx 0;border-bottom:2rpx solid $line}.option{display:flex;justify-content:space-between;gap:20rpx;align-items:center;padding:24rpx 0}.option>view{flex:1}</style>
